__d(function(e,i,t,o,n,a,s){n.exports={version:"2.0",board:"Karnataka State Board / NCERT",grade:7,subject:"Mathematics",textbook:"Mathematics \u2014 Textbook for Class VII",chapter_number:1,chapter_title:"Integers",quiz_type:"MCQ only",mcqs:[{id:"mcq01",difficulty:"Easy",question:"What is (\u22128) + (\u22125)?",options:["A) 13","B) \u221213","C) 3","D) \u22123"],correct_answer:"B) \u221213",explanation:"Adding two negative integers: take their absolute values, add them, and keep the negative sign. |\u22128| + |\u22125| = 8 + 5 = 13. Both are negative, so result = \u221213."},{id:"mcq02",difficulty:"Easy",question:"What is 6 \u2212 (\u22124)?",options:["A) 2","B) \u22122","C) 10","D) \u221210"],correct_answer:"C) 10",explanation:"Subtracting a negative integer = adding its positive: 6 \u2212 (\u22124) = 6 + 4 = 10. Rule: a \u2212 (\u2212b) = a + b. This is one of the most commonly tested concepts in this chapter."},{id:"mcq03",difficulty:"Easy",question:"What is (\u22127) \xd7 (\u22128)?",options:["A) \u221256","B) 56","C) \u221215","D) 15"],correct_answer:"B) 56",explanation:"Negative \xd7 Negative = Positive. (\u22127) \xd7 (\u22128) = +(7 \xd7 8) = +56. Same signs give a positive product. This is the 'enemy of my enemy is my friend' rule."},{id:"mcq04",difficulty:"Easy",question:"What is (\u221236) \xf7 (+9)?",options:["A) 4","B) \u22124","C) 27","D) \u221227"],correct_answer:"B) \u22124",explanation:"Negative \xf7 Positive = Negative. (\u221236) \xf7 9 = \u2212(36 \xf7 9) = \u22124. Different signs give a negative quotient. Check: (\u22124) \xd7 9 = \u221236 \u2713."},{id:"mcq05",difficulty:"Easy",question:"The additive inverse of \u221215 is:",options:["A) 15","B) \u221215","C) 0","D) 1"],correct_answer:"A) 15",explanation:"The additive inverse of an integer a is \u2212a, such that a + (\u2212a) = 0. Additive inverse of \u221215 = \u2212(\u221215) = 15. Check: \u221215 + 15 = 0 \u2713."},{id:"mcq06",difficulty:"Easy",question:"Which property is shown by: (\u22124) \xd7 [(\u22123) + 5] = (\u22124) \xd7 (\u22123) + (\u22124) \xd7 5?",options:["A) Commutative","B) Associative","C) Distributive","D) Closure"],correct_answer:"C) Distributive",explanation:"The distributive property: a \xd7 (b + c) = a\xd7b + a\xd7c. Here a = \u22124, b = \u22123, c = 5. The multiplication is distributed over the addition inside the bracket."},{id:"mcq07",difficulty:"Easy",question:"What is (\u22121) \xd7 (\u22121) \xd7 (\u22121) \xd7 (\u22121)?",options:["A) \u22121","B) 1","C) \u22124","D) 4"],correct_answer:"B) 1",explanation:"Count the negative integers: 4 negatives (EVEN number). Even number of negatives \u2192 positive product. Product of absolute values = 1\xd71\xd71\xd71 = 1. Answer: +1."},{id:"mcq08",difficulty:"Easy",question:"Temperature at midnight was \u22123\xb0C. By 8 AM it rose by 11\xb0C. What is the temperature at 8 AM?",options:["A) \u221214\xb0C","B) 14\xb0C","C) 8\xb0C","D) \u22128\xb0C"],correct_answer:"C) 8\xb0C",explanation:"\u22123 + 11 = 8\xb0C. Rising temperature = adding a positive integer. Start at \u22123 on number line, move 11 steps right, land at 8. Temperature at 8 AM = 8\xb0C."},{id:"mcq09",difficulty:"Easy",question:"Which of the following is NOT an integer?",options:["A) \u22125","B) 0","C) 3/4","D) 100"],correct_answer:"C) 3/4",explanation:"Integers include all positive whole numbers, negative whole numbers, and zero. Fractions like 3/4 are NOT integers. \u22125, 0, and 100 are all integers."},{id:"mcq10",difficulty:"Easy",question:"What is 0 \xf7 (\u22127)?",options:["A) \u22127","B) 7","C) 0","D) Undefined"],correct_answer:"C) 0",explanation:"0 divided by any non-zero integer = 0. Check: 0 \xf7 (\u22127) = 0 because 0 \xd7 (\u22127) = 0 \u2713. Note: this is different from (\u22127) \xf7 0, which is UNDEFINED."},{id:"mcq11",difficulty:"Moderate",question:"What is (\u22123) \xd7 (\u22124) \xd7 (\u22122) \xd7 (\u22121)?",options:["A) \u221224","B) 24","C) \u221210","D) 10"],correct_answer:"B) 24",explanation:"Count negatives: 4 (EVEN). Even negatives \u2192 positive product. Absolute values: 3 \xd7 4 \xd7 2 \xd7 1 = 24. Answer: +24."},{id:"mcq12",difficulty:"Moderate",question:"Using the distributive property, evaluate (\u221212) \xd7 98.",options:["A) \u22121176","B) 1176","C) \u22121200","D) \u2212984"],correct_answer:"A) \u22121176",explanation:"Write 98 = 100 \u2212 2. (\u221212) \xd7 98 = (\u221212) \xd7 100 \u2212 (\u221212) \xd7 2 = \u22121200 \u2212 (\u221224) = \u22121200 + 24 = \u22121176."},{id:"mcq13",difficulty:"Moderate",question:"In a quiz: correct = +3, wrong = \u22121. Rahul answers 10 correct and 4 wrong. His score is:",options:["A) 26","B) 30","C) 34","D) 6"],correct_answer:"A) 26",explanation:"Correct: 10 \xd7 3 = 30. Wrong: 4 \xd7 (\u22121) = \u22124. Total = 30 + (\u22124) = 26."},{id:"mcq14",difficulty:"Moderate",question:"Which of these equations is TRUE?",options:["A) (\u22125) \u2212 (\u22123) = \u22128","B) (\u22125) \u2212 (\u22123) = \u22122","C) (\u22125) \u2212 (\u22123) = 2","D) (\u22125) \u2212 (\u22123) = 8"],correct_answer:"B) (\u22125) \u2212 (\u22123) = \u22122",explanation:"(\u22125) \u2212 (\u22123) = (\u22125) + 3 = \u22122. Subtracting (\u22123) means adding +3. \u22125 + 3 = \u22122 (since |\u22125| > |3|, result takes sign of \u22125)."},{id:"mcq15",difficulty:"Moderate",question:"Which property is demonstrated: (\u22125) + 0 = \u22125?",options:["A) Additive Inverse","B) Additive Identity","C) Commutative","D) Associative"],correct_answer:"B) Additive Identity",explanation:"The Additive Identity property: a + 0 = a. Adding zero to any integer leaves it unchanged. 0 is the additive identity. This is different from Additive Inverse (a + (\u2212a) = 0)."},{id:"mcq16",difficulty:"Moderate",question:"A lift starts at floor 0, goes down 5 floors, then up 8 floors, then down 3 floors. Where does it stop?",options:["A) Floor 0","B) Floor 3","C) Floor \u22123","D) Floor 16"],correct_answer:"A) Floor 0",explanation:"0 + (\u22125) + 8 + (\u22123) = \u22125 + 8 \u2212 3 = 3 \u2212 3 = 0. The lift ends at floor 0 (ground floor). Down = negative, Up = positive."},{id:"mcq17",difficulty:"Moderate",question:"Find the missing integer \u2605: \u2605 \xd7 (\u22126) = 54",options:["A) 9","B) \u22129","C) 48","D) \u221248"],correct_answer:"B) \u22129",explanation:"\u2605 \xd7 (\u22126) = 54. So \u2605 = 54 \xf7 (\u22126) = \u22129. Check: (\u22129) \xd7 (\u22126) = +54 \u2713. (Negative \xd7 negative = positive.)"},{id:"mcq18",difficulty:"Moderate",question:"Are integers closed under division? Justify.",options:["A) Yes \u2014 dividing two integers always gives an integer","B) No \u2014 (\u22127) \xf7 2 = \u22123.5, which is not an integer","C) Yes \u2014 division is the inverse of multiplication","D) No \u2014 you cannot divide negative integers"],correct_answer:"B) No \u2014 (\u22127) \xf7 2 = \u22123.5, which is not an integer",explanation:"Closure under division fails because dividing two integers does not always give an integer. (\u22127) \xf7 2 = \u22123.5 is a decimal, not an integer. Integers are only closed under addition, subtraction, and multiplication."},{id:"mcq19",difficulty:"Advanced",question:"If a = \u22123, b = 4, c = \u22122, verify: a \xd7 (b + c) = a\xd7b + a\xd7c and find the value.",options:["A) 6","B) \u22126","C) 12","D) \u221212"],correct_answer:"A) 6",explanation:"Method 1: b + c = 4 + (\u22122) = 2. a \xd7 (b+c) = (\u22123) \xd7 2 = \u22126. Wait \u2014 recheck. Method 2: a\xd7b + a\xd7c = (\u22123)\xd74 + (\u22123)\xd7(\u22122) = \u221212 + 6 = \u22126. Both = \u22126. Note: correct answer should be \u22126. a \xd7 (b+c) = (\u22123)(4+(\u22122)) = (\u22123)(2) = \u22126."},{id:"mcq20",difficulty:"Advanced",question:"The product of two integers is \u2212120. If one integer is \u22128, which of the following could be the other integer?",options:["A) 15","B) \u221215","C) 12","D) \u221212"],correct_answer:"A) 15",explanation:"(\u22128) \xd7 ? = \u2212120. ? = (\u2212120) \xf7 (\u22128) = +15. Check: (\u22128) \xd7 15 = \u2212120 \u2713. Since the product is negative and one factor is \u22128 (negative), the other must be positive. So ? = +15."}]}},2770,[]);